INSERT INTO vocab_library_words VALUES ('2862ab1c-18be-415e-a680-80873eaa72d4', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'petulant', '토라진, 짜증을 잘 내는', '{sulky,peevish}', '{gracious,amiable}', 'The petulant child refused to eat dinner after being told he could not have dessert first.', 'Her petulant tone during the meeting surprised colleagues who knew her as calm and patient.', 3, '2026-09-16 09:19:02.38431+00', 3, '인물 대화·감정 묘사 지문에서 태도를 세밀히 구분하는 어휘') ON CONFLICT DO NOTHING;
