INSERT INTO vocab_library_words VALUES ('1fb9d139-4633-4ea2-96d5-109b4714a996', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'stolid', '감정을 잘 드러내지 않고 무덤덤한', '{impassive,unemotional}', '{expressive,excitable}', 'The stolid expression on his face gave no hint of the turmoil he felt inside.', 'Despite the chaos around her, she remained stolid, unmoved by the panic.', 137, '2026-09-16 09:19:02.38431+00', 4, '인물 성격 묘사 지문에서 감정 억제형 인물을 설명할 때 자주 사용') ON CONFLICT DO NOTHING;
