INSERT INTO vocab_library_words VALUES ('84443410-7401-453d-9458-e89ec0e64957', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'vexation', '짜증, 화나게 하는 감정 상태', '{irritation,annoyance}', '{contentment,satisfaction}', 'Her vexation grew as the technical issues delayed the presentation further.', 'He hid his vexation behind a polite smile during the tedious meeting.', 166, '2026-09-16 09:19:02.38431+00', 3, '인물의 미묘한 감정 변화를 서술하는 지문에서 자주 쓰이는 명사형 어휘') ON CONFLICT DO NOTHING;
