INSERT INTO vocab_library_words VALUES ('0d3ca01c-a501-40ce-bd31-4a3097a185e4', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'acumen', '예리한 판단력이나 통찰력', '{shrewdness,perspicacity}', '{obtuseness,ineptitude}', 'Her business acumen allowed her to spot opportunities others missed.', 'The critic''s literary acumen revealed subtleties in the text overlooked by casual readers.', 168, '2026-09-16 09:19:02.38431+00', 3, '인물의 지적 태도를 묘사하는 지문에서 자주 등장') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('531cce57-88fe-4f23-aa6d-df8bfa240397', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'equipoise', '감정이나 태도의 균형 잡힌 안정 상태', '{composure,equanimity}', '{agitation,turmoil}', 'He maintained an equipoise of emotion even as chaos surrounded him.', 'Her equipoise under pressure impressed the entire negotiating team.', 169, '2026-09-16 09:19:02.38431+00', 4, '성격·태도 지문에서 평정심을 나타내는 고급 어휘') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('3038635b-282d-42bc-a684-2cd6c55af5f3', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'exasperation', '짜증과 답답함이 뒤섞인 감정 상태', '{frustration,irritation}', '{contentment,calm}', 'His exasperation grew as the meeting dragged on without resolution.', 'She sighed in exasperation when the printer jammed for the third time.', 170, '2026-09-16 09:19:02.38431+00', 3, '인물 감정 상태를 세밀히 구분하는 지문에서 빈출') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('c53f75e7-4b29-495f-bf10-4e7477d52530', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'reticence', '말을 아끼고 조심스러운 태도', '{reserve,taciturnity}', '{loquacity,candor}', 'His reticence about his past made colleagues curious.', 'Despite her reticence in meetings, she offered sharp insights when asked directly.', 171, '2026-09-16 09:19:02.38431+00', 3, '인물의 말투와 태도를 구분하는 지문에서 빈출') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('5972d2ae-178c-4d88-89ed-69076cc84f79', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'disdain', '경멸하거나 얕보는 태도', '{contempt,scorn}', '{admiration,respect}', 'She regarded the proposal with open disdain, dismissing it without discussion.', 'His disdain for shortcuts pushed him to redo the entire project.', 172, '2026-09-16 09:19:02.38431+00', 3, '인물 간 관계와 태도를 묘사하는 지문에서 필수 어휘') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('1c112723-81bb-4b9d-9e68-2b8e3097f2ef', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'trepidation', '불안하고 두려운 마음 상태', '{apprehension,anxiety}', '{confidence,assurance}', 'She approached the podium with visible trepidation before her speech.', 'His trepidation about the diagnosis kept him awake all night.', 173, '2026-09-16 09:19:02.38431+00', 3, '인물의 감정 상태를 정교하게 묘사하는 지문에서 빈출') ON CONFLICT DO NOTHING;
