INSERT INTO vocab_library_words VALUES ('72c7825c-eede-4c78-aeeb-60f477af5015', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'probity', '정직하고 도덕적으로 올바른 성품', '{integrity,honesty}', '{corruption,dishonesty}', 'The judge was known for his probity, never swayed by bribery or pressure.', 'Her probity in handling the funds earned the trust of every donor.', 175, '2026-09-16 09:19:02.38431+00', 4, '인물의 도덕적 성품을 평가하는 지문에서 자주 등장') ON CONFLICT DO NOTHING;
