INSERT INTO vocab_library_words VALUES ('0856c753-4cf5-45d0-91bb-4010e7b7fd5a', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'forbearance', '인내하며 화를 참는 절제된 태도', '{patience,restraint}', '{impatience,irritability}', 'Her forbearance with the difficult client impressed her supervisors.', 'He showed remarkable forbearance despite repeated provocations.', 178, '2026-09-16 09:19:02.38431+00', 4, '인물의 절제된 감정 태도를 다루는 지문에서 필수 어휘') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('31471d88-11d1-4d18-ae9b-1205adf4eccd', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'cantankerousness', '괴팍하고 잘 다투는 성향', '{irritability,crustiness}', '{amiability,affability}', 'The old man''s cantankerousness scared away most visitors.', 'Despite his cantankerousness, his students respected his sharp mind.', 179, '2026-09-16 09:19:02.38431+00', 4, '인물 성격을 부정적으로 묘사할 때 등장하는 어휘') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('4172fdb9-4f36-4c52-91f4-0934558d20f0', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'stoutness', '용기와 결단력이 강한 성품 (여기서는 심리적 강인함)', '{fortitude,resolve}', '{weakness,cowardice}', 'Her stoutness of spirit helped her endure years of hardship.', 'The soldiers admired their commander''s stoutness in the face of defeat.', 180, '2026-09-16 09:19:02.38431+00', 4, '인물의 내적 강인함을 표현하는 지문에서 사용되는 어휘') ON CONFLICT DO NOTHING;
