INSERT INTO vocab_library_words VALUES ('72a1539d-b044-4d08-b4f0-7d5760b8da8a', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'obtrude', '주제넘게 끼어들다, 강요하다', '{intrude,impose}', '{withdraw,refrain}', 'He tended to obtrude his opinions into conversations that did not concern him.', 'She never obtruded upon others'' private matters, preferring quiet observation.', 190, '2026-09-16 09:19:02.38431+00', 4, '인물의 사회적 태도를 평가하는 지문에서 사용되는 동사') ON CONFLICT DO NOTHING;
