INSERT INTO vocab_library_words VALUES ('3c0a854c-1dfb-4320-b256-a292fee45b5a', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'prickliness', '쉽게 짜증내는 성향, 까칠함', '{irritability,touchiness}', '{mildness,calmness}', 'His prickliness toward criticism made feedback sessions unusually tense.', 'Despite her prickliness, colleagues respected her honesty and diligence.', 193, '2026-09-16 09:19:02.38431+00', 4, '성격 특성을 설명하는 인물 묘사 지문에서 등장') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('29f19e6a-2073-46b9-84dc-272a6667faa7', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'guilelessness', '순진함, 꾸밈없는 솔직함', '{naivety,innocence}', '{cunning,deceit}', 'The child''s guilelessness disarmed even the most cynical adults at the table.', 'Her guilelessness in business dealings occasionally left her vulnerable to exploitation.', 194, '2026-09-16 09:19:02.38431+00', 4, '인물의 순수한 성격을 대조적으로 묘사하는 지문에서 사용') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('a0e84c5b-e882-49f5-aac2-d7a3865442b8', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'waspishness', '까칠하고 신경질적인 태도', '{irritability,sharpness}', '{gentleness,affability}', 'The critic''s waspishness toward young writers earned him few admirers.', 'Her waspishness during the meeting was uncharacteristic of her usual calm demeanor.', 195, '2026-09-16 09:19:02.38431+00', 4, '인물의 신경질적 태도를 묘사하는 명사형 어휘') ON CONFLICT DO NOTHING;
