INSERT INTO vocab_library_words VALUES ('494133f8-f811-41c0-817f-dff9d6e39731', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'rancorous', '깊은 원한이 담긴, 적의에 찬', '{bitter,resentful}', '{forgiving,amicable}', 'The rancorous dispute between the former partners lasted for years.', 'His rancorous tone during the debate surprised those who knew him as mild-mannered.', 197, '2026-09-16 09:19:02.38431+00', 4, '인물 간 갈등을 다루는 지문에서 감정 강도를 나타낼 때 사용') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('9a07414d-d1ab-4348-8e42-82eb6ba1ded6', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'forthrightness', '솔직함, 직설적인 태도', '{candor,directness}', '{evasiveness,duplicity}', 'Her forthrightness in the meeting, though blunt, was widely appreciated by the staff.', 'He valued forthrightness over diplomatic evasion, even when the truth was unwelcome.', 198, '2026-09-16 09:19:02.38431+00', 4, '인물의 솔직한 태도를 강조하는 명사형 어휘로 지문에 자주 등장') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('679180ee-a8f2-44a5-94af-f4bcc2be3cd8', 'b5e1b821-b5d6-4cff-9b69-91fc15ab022a', 'complaisance', '남을 기쁘게 하려는 태도, 공손한 순응', '{obligingness,deference}', '{obstinacy,defiance}', 'His complaisance toward every guest''s request left little room for his own preferences.', 'The clerk''s complaisance, while polite, sometimes bordered on excessive deference.', 199, '2026-09-16 09:19:02.38431+00', 4, '인물의 지나치게 순응적인 태도를 묘사할 때 쓰이는 명사') ON CONFLICT DO NOTHING;
